            ls = Path(p).read_text().splitlines()
            content = ls[n-1] if n-1 < len(ls) else '<OUT OF RANGE>'
        except Exception as e:
            content = f'<ERR {e}>'
        print(f'  {p}:{n} -> {content[:300]}')
