import re, os
from pathlib import Path
target = Path('.skilled/skills/mcp-tooling/mcp-chrome-devtools/references/troubleshooting.md').resolve()
hits=[]
for p in Path('.skilled/skills').rglob('*.md'):
    try: txt=p.read_text()
    except: continue
    for m in re.finditer(r'\[[^\]]*\]\(([^)]+)\)', txt):
        link=m.group(1).split('#')[0]
        if not link or link.startswith(('http','mailto')): continue
        q=(p.parent/link).resolve()
        if q==target:
            hits.append((str(p), txt[:m.start()].count('\n')+1, m.group(0)[:160]))
print('resolved-link hits:',len(hits))
for h in hits[:40]: print(h)
# also plain path mentions
print('--- plain mentions ---')
for p in Path('.skilled/skills').rglob('*.md'):
    if 'changelog' in str(p): continue
    try: lines=p.read_text().splitlines()
    except: continue
    for i,l in enumerate(lines,1):
        if 'mcp-chrome-devtools/references/troubleshooting.md' in l:
            print(p,i,l[:200])
